import org.jsoup.Connection;
import org.junit.Assert;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.UnsupportedEncodingException;
import java.net.MalformedURLException;
import java.net.URL;


@RunWith(MockitoJUnitRunner.class)
public class UrlBuilderTest {

    @Mock
    private Connection.KeyVal mockKeyVal;

    @Test
    public void UrlBuilderConstructorTest() {
        URL url = null;

        try {
            url = new URL("http://www.example.com");
        } catch (MalformedURLException e) {
            Assert.fail("Could not construct URL: " + e.getMessage());
        }

        UrlBuilder urlBuilder = new UrlBuilder(url);
        Assert.assertNotNull(urlBuilder);
    }

    @Test
    public void BuildValidUrlTest() {
        URL url = null;

        try {
            url = new URL("http://www.example.com");
        } catch (MalformedURLException e) {
            Assert.fail("Could not construct URL: " + e.getMessage());
        }

        UrlBuilder urlBuilder = new UrlBuilder(url);
        URL builtUrl = urlBuilder.build();

        Assert.assertEquals(url, builtUrl);
    }

	@Test(expected = NullPointerException.class)
    public void BuildInvalidUrlTest() {
        UrlBuilder urlBuilder = new UrlBuilder(null);
        URL builtUrl = urlBuilder.build();
        Assert.assertNull(builtUrl);
    }

    @Test
    public void AppendKeyValValidTest() {
        URL url = null;

        try {
            url = new URL("http://www.example.com");
        } catch (MalformedURLException e) {
            Assert.fail("Could not construct URL: " + e.getMessage());
        }

        UrlBuilder urlBuilder = new UrlBuilder(url);
        try {
            urlBuilder.appendKeyVal(mockKeyVal);
        } catch (UnsupportedEncodingException e) {
            Assert.fail("Could not append KeyVal: " + e.getMessage());
        }
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void AppendKeyValInvalidTest() throws UnsupportedEncodingException {
        URL url = null;

        try {
            url = new URL("http://www.example.com");
        } catch (MalformedURLException e) {
            Assert.fail("Could not construct URL: " + e.getMessage());
        }

        UrlBuilder urlBuilder = new UrlBuilder(url);
        urlBuilder.appendKeyVal(null);
    }
}
